I vibe coded a raw cancelation request, just a fun note Opus 4.5 struggled to find the solution and OpenAI Codex 5.2 fixed.

```javascript
import { getEnv } from '@/lib/get-env';
import { temporal } from "@temporalio/proto";


async function cancelWorkflowManual(
    temporalUrl: string,
    apiKey: string,
    namespace: string,
    workflowId: string,
    runId?: string
) {
    const frameGrpcMessage = (message: Uint8Array) => {
        const framed = new Uint8Array(5 + message.length);
        framed[0] = 0; // compression flag: 0 = not compressed
        const view = new DataView(framed.buffer);
        view.setUint32(1, message.length);
        framed.set(message, 5);
        return framed;
    };

    // Create the request message using protobufjs
    const request = temporal.api.workflowservice.v1.RequestCancelWorkflowExecutionRequest.create({
        namespace: namespace,
        workflowExecution: {
            workflowId: workflowId,
            runId: runId || undefined
        },
        requestId: crypto.randomUUID(),
        reason: "Cancelled by user"
    });

    // Encode to binary protobuf format
    const encodedRequest = temporal.api.workflowservice.v1.RequestCancelWorkflowExecutionRequest
        .encode(request)
        .finish();

    const framedRequest = frameGrpcMessage(encodedRequest);

    // gRPC protocol (unary POST with framed protobuf)
    const response = await fetch(
        `https://${temporalUrl}/temporal.api.workflowservice.v1.WorkflowService/RequestCancelWorkflowExecution`,
        {
            method: "POST",
            headers: {
                "Authorization": `Bearer ${apiKey}`,
                "Content-Type": "application/grpc+proto",
                "TE": "trailers",
                "Temporal-Namespace": namespace,
            },
            body: framedRequest as unknown as BodyInit
        }
    );

    if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`gRPC error: ${response.status} ${response.statusText} - ${errorText}`);
    }

    // Decode the response (gRPC framed)
    const responseBuffer = await response.arrayBuffer();
    const responseBytes = new Uint8Array(responseBuffer);
    if (responseBytes.length < 5) {
        throw new Error("gRPC response too short");
    }
    const responseLength = new DataView(responseBytes.buffer).getUint32(1);
    const messageBytes = responseBytes.slice(5, 5 + responseLength);
    const decodedResponse = temporal.api.workflowservice.v1.RequestCancelWorkflowExecutionResponse
        .decode(messageBytes);

    return decodedResponse;
}

export default async function Page() {
    let status = "idle";
    let error: string | null = null;

    try {
        const temporalUrl = await getEnv('TEMPORAL_URL');
        const temporalApiKey = await getEnv('TEMPORAL_API_KEY');
        const temporalNamespace = await getEnv('TEMPORAL_NAMESPACE');

        // Cancel the workflow using manual serialization
        const workflowId = "new-project-version-15-48";
        await cancelWorkflowManual(
            temporalUrl,
            temporalApiKey,
            temporalNamespace,
            workflowId
        );

        console.log("Workflow cancellation requested successfully");
        status = "success";

    } catch (err) {
        console.error("Failed to cancel workflow:", err);
        if (err instanceof Error) {
            console.error("Stack:", err.stack);
            error = err.message;
        }
        status = "error";
    }

    return (
        <div>
            <h1>Temporal Workflow</h1>
            <p>Status: {status}</p>
            {error && <p style={{ color: 'red' }}>Error: {error}</p>}
        </div>
    )
}
